import {Caption} from '@jetbrains/ring-ui-built/components/button-group/button-group'
import type {ToggleTagParams} from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import TagsInput from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import classNames from 'classnames'
import * as React from 'react'
import {useMemo} from 'react'
import {usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {RingTag} from '../../../../../../../types'
import {notNull} from '../../../../../../../utils/guards'
import type {CleanupFormBuildTypeTagsQuery} from '../__generated__/CleanupFormBuildTypeTagsQuery.graphql'
import {LoadingContext, DispatchContext} from '../CleanupForm.contexts'
import styles from '../CleanupForm.module.css'
import {buildTypeTagsQuery} from '../CleanupForm.queries'

export const tagsConverter = {
  toRule: (tags: ReadonlyArray<RingTag>): string => tags.map(tag => tag.key).join('\n'),
  toForm: (tagsList: string | null | undefined): ReadonlyArray<RingTag> =>
    (typeof tagsList === 'string' &&
      tagsList
        .split('\n')
        .filter(Boolean)
        .map(item => ({
          key: item,
          label: item,
        }))) ||
    [],
}
type Props = {
  value: ReadonlyArray<RingTag>
  buildTypeTagsQueryRef: PreloadedQuery<CleanupFormBuildTypeTagsQuery>
}

function TagSection({value, buildTypeTagsQueryRef}: Props) {
  const {buildTypeBuildTags} = usePreloadedQuery(buildTypeTagsQuery, buildTypeTagsQueryRef)
  const availableTags = useMemo(
    () => buildTypeBuildTags?.tag?.map(tag => tag.name).filter(notNull) ?? [],
    [buildTypeBuildTags],
  )

  const disabled = React.useContext(LoadingContext)
  const setValue = React.useContext(DispatchContext)
  const onChange = React.useCallback(
    (values: RingTag[]) =>
      setValue?.({
        name: 'tags',
        value: values,
      }),
    [setValue],
  )
  const onAddTag = React.useCallback(
    ({tag}: ToggleTagParams) => onChange([...value, tag]),
    [onChange, value],
  )
  const onRemoveTag = React.useCallback(
    ({tag}: ToggleTagParams) => onChange(value.filter(item => item.key !== tag.key)),
    [onChange, value],
  )
  const dataSource = React.useCallback(
    () =>
      availableTags.map(tagName => ({
        key: tagName,
        label: tagName,
      })),
    [availableTags],
  )

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' && !event.metaKey && !event.ctrlKey) {
      event.preventDefault()
    }
  }

  return (
    <div className={styles.row}>
      <Caption className={styles.caption}>{'Tags'}</Caption>
      <div className={styles.content}>
        <div className={classNames(styles.inputs)} onKeyDown={handleKeyDown} role="presentation">
          <TagsInput
            disabled={disabled}
            placeholder={'Select tags to add'}
            tags={value}
            dataSource={dataSource}
            allowAddNewTags
            filter
            onAddTag={onAddTag}
            onRemoveTag={onRemoveTag}
          />
        </div>
        <div className={styles.hint}>{'Matches builds with any specified tag'}</div>
      </div>
    </div>
  )
}

export default React.memo(TagSection)
