import {connect} from 'react-redux'
import type {EntryPointProps} from 'react-relay'

import type {State} from '../../../../../../reducers/types'
import type {BranchSelectBranchesQuery} from '../../../../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import {isAnyActionPerforming, isCustomErrorExists} from '../Rules.selectors'

import type {CleanupFormBuildTypeTagsQuery} from './__generated__/CleanupFormBuildTypeTagsQuery.graphql'
import CleanupForm from './CleanupForm'
import type {OwnProps, StateProps, OuterProps} from './CleanupForm.types'

const mapStateToProps = (state: State, {holderNode}: OwnProps): StateProps => ({
  loading: isAnyActionPerforming(state, holderNode),
  customError: isCustomErrorExists(state),
})

const CleanupFormContainer = connect(mapStateToProps)(CleanupForm)

type Queries = {
  branches: BranchSelectBranchesQuery
  buildTypeTags: CleanupFormBuildTypeTagsQuery
}

export default function CleanupFormOuterContainer({
  queries,
  props,
}: EntryPointProps<Queries, {}, OuterProps, {}>) {
  return (
    <CleanupFormContainer
      {...props}
      branchesQueryRef={queries.branches}
      buildTypeTagsQueryRef={queries.buildTypeTags}
    />
  )
}
export type CleanupFormOuterContainerComponent = typeof CleanupFormOuterContainer
